sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var cloneGR = new GlideRecord('clone_instance');
    cloneGR.addQuery('state', 'completed');
    cloneGR.orderByDesc('sys_created_on');
    cloneGR.setLimit(1);
    cloneGR.query();

    var startDate;
    if (cloneGR.next()) {
        startDate = cloneGR.getValue('sys_created_on');
    } else {
        startDate = new GlideDateTime('2024-03-08 00:00:00');
    }

    //var startDate = new GlideDateTime('2024-03-08 00:00:00');

    var tableGR = new GlideRecord('sys_db_object');
    //MSSOTIQUBE-2474
    tables.addQuery('name', 'NOT LIKE', '%$%');
    tableGR.addQuery('sys_created_on', '>', startDate);
    //tableGR.setLimit(1);
    tableGR.query();


    while (tableGR.next()) {
        var tableName = tableGR.getValue('name');
        var tableLabel = tableGR.getValue('label');


        var preserverGR = new GlideRecord('clone_data_preserver');
        preserverGR.initialize();
        preserverGR.setValue('table', tableName);
        preserverGR.setValue('name', tableLabel);
        preserverGR.insert();
    }


})(current, previous);
